create table if not exists public.project_progress_submissions (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.projects(id) on delete cascade,
  submitted_by uuid not null references public.profiles(id) on delete restrict,
  activity_count integer not null default 0 check (activity_count >= 0),
  submitted_at timestamptz not null default timezone('utc', now())
);
create index if not exists progress_submissions_project_idx on public.project_progress_submissions(project_id,submitted_at desc);
alter table public.project_progress_submissions enable row level security;
drop policy if exists "progress submissions readable by project members" on public.project_progress_submissions;
create policy "progress submissions readable by project members" on public.project_progress_submissions for select using (
  exists (select 1 from public.projects p where p.id = project_id and (public.is_ceo() or p.assigned_engineer_id = auth.uid()))
);
drop policy if exists "progress submissions created by assigned engineer" on public.project_progress_submissions;
create policy "progress submissions created by assigned engineer" on public.project_progress_submissions for insert with check (
  submitted_by = auth.uid() and exists (select 1 from public.projects p where p.id = project_id and p.assigned_engineer_id = auth.uid())
);



-- Source: project-progress-updates.sql

create table if not exists public.project_progress_updates (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.projects(id) on delete cascade,
  submitted_by uuid not null references public.profiles(id) on delete restrict,
  overall_percent numeric(5,2) not null check (overall_percent >= 0 and overall_percent <= 100),
  completed_work_summary text not null check (char_length(trim(completed_work_summary)) between 1 and 1000),
  remarks text check (remarks is null or char_length(remarks) <= 600),
  progress_date date not null default (timezone('Asia/Manila', now()))::date,
  created_at timestamptz not null default timezone('utc', now())
);

alter table public.project_progress_updates
  add column if not exists progress_date date;

update public.project_progress_updates
set progress_date = (timezone('Asia/Manila', created_at))::date
where progress_date is null;

alter table public.project_progress_updates
  alter column progress_date set default (timezone('Asia/Manila', now()))::date,
  alter column progress_date set not null;

create index if not exists project_progress_updates_project_created_idx
  on public.project_progress_updates(project_id, created_at desc);

create index if not exists project_progress_updates_project_date_idx
  on public.project_progress_updates(project_id, progress_date desc, created_at desc);

alter table public.project_progress_updates enable row level security;

drop policy if exists "progress updates readable by project members" on public.project_progress_updates;
create policy "progress updates readable by project members"
  on public.project_progress_updates for select
  using (
    public.is_ceo()
    or exists (
      select 1 from public.projects projects
      where projects.id = project_progress_updates.project_id
        and (
          projects.assigned_engineer_id = auth.uid()
          or projects.assigned_estimate_engineer_id = auth.uid()
        )
    )
  );

drop policy if exists "progress updates created by assigned site engineer" on public.project_progress_updates;
create policy "progress updates created by assigned site engineer"
  on public.project_progress_updates for insert
  with check (
    submitted_by = auth.uid()
    and exists (
      select 1 from public.projects projects
      where projects.id = project_progress_updates.project_id
        and projects.assigned_engineer_id = auth.uid()
    )
  );

-- Source: gmea-08-project-status.sql
-- Adds an active/completed lifecycle without removing project history.
-- Safe to run after gmea-01 through gmea-07 on new or existing environments.
alter table public.gmea_projects
  add column if not exists status text,
  add column if not exists completed_at timestamptz,
  add column if not exists completed_by uuid references public.profiles(id) on delete set null;

update public.gmea_projects set status='active' where status is null;

alter table public.gmea_projects
  alter column status set default 'active',
  alter column status set not null;

do $$
begin
  if not exists(
    select 1 from pg_constraint
    where conname='gmea_project_status_valid'
      and conrelid='public.gmea_projects'::regclass
  ) then
    alter table public.gmea_projects
      add constraint gmea_project_status_valid
      check(status in ('active','completed'));
  end if;
end $$;

do $$
begin
  if to_regprocedure('public.mutate_gmea_project_without_status(uuid,uuid,integer,jsonb)') is null then
    alter function public.mutate_gmea_project(uuid,uuid,integer,jsonb)
      rename to mutate_gmea_project_without_status;
  end if;
end $$;

create or replace function public.mutate_gmea_project(
  p_actor uuid,
  p_project uuid,
  p_version integer,
  p_command jsonb
)
returns uuid language plpgsql security definer set search_path=public as $$
declare
  current_project public.gmea_projects;
  next_status text;
begin
  if p_command->>'kind'<>'project_status' then
    return public.mutate_gmea_project_without_status(
      p_actor,
      p_project,
      p_version,
      p_command
    );
  end if;

  if not exists(
    select 1 from public.profiles
    where id=p_actor and role::text='gmea' and is_active
  ) then
    raise exception 'Only active GMEA users can manage projects';
  end if;
  if p_project is null then raise exception 'Create a project first'; end if;

  select * into current_project
  from public.gmea_projects
  where id=p_project
  for update;
  if not found then raise exception 'Project not found'; end if;
  if p_version is distinct from current_project.version then
    raise exception 'This project changed. Reload the page before saving again.';
  end if;

  next_status:=p_command->'value'->>'status';
  if next_status not in ('active','completed') then
    raise exception 'Select a valid project status.';
  end if;

  update public.gmea_projects set
    status=next_status,
    completed_at=case when next_status='completed' then now() else null end,
    completed_by=case when next_status='completed' then p_actor else null end,
    updated_by=p_actor,
    version=version+1,
    updated_at=now()
  where id=p_project;

  return p_project;
end $$;

revoke all on function public.mutate_gmea_project_without_status(uuid,uuid,integer,jsonb)
  from public,anon,authenticated;
grant execute on function public.mutate_gmea_project_without_status(uuid,uuid,integer,jsonb)
  to service_role;
revoke all on function public.mutate_gmea_project(uuid,uuid,integer,jsonb)
  from public,anon,authenticated;
grant execute on function public.mutate_gmea_project(uuid,uuid,integer,jsonb)
  to service_role;
notify pgrst, 'reload schema';
commit;
